function clampLayoutPercent(value, min, max) {
    return Math.min(max, Math.max(min, value));
}
function normalizeTemplateWindowOrder(value) {
    const incoming = Array.isArray(value) ? value : [];
    const seen = new Set();
    const normalized = [];
    for (const entry of incoming){
        const id = String(entry || "").trim().toLowerCase();
        if (!TEMPLATE_WINDOW_IDS.includes(id) || seen.has(id)) continue;
        seen.add(id);
        normalized.push(id);
    }
    for (const id of TEMPLATE_WINDOW_IDS){
        if (!seen.has(id)) normalized.push(id);
    }
    return normalized;
}
function normalizeTemplateDeckWindowOrder(value) {
    return normalizeTemplateWindowOrder(value).filter((item)=>item !== "preview");
}
function normalizeRecoveryLayoutConfig(payload) {
    const templates = payload?.templates;
    return {
        templates: {
            historyPosition: templates?.historyPosition === "before" ? "before" : "after",
            workspaceMode: templates?.workspaceMode === "column" ? "column" : "row",
            workspaceLeadPane: templates?.workspaceLeadPane === "catalog" ? "catalog" : "composer",
            windowOrder: normalizeTemplateWindowOrder(templates?.windowOrder),
            workspacePrimaryPercent: clampLayoutPercent(Number(templates?.workspacePrimaryPercent || DEFAULT_RECOVERY_LAYOUT_CONFIG.templates.workspacePrimaryPercent), 40, 72),
            catalogHeight: clampLayoutPercent(Number(templates?.catalogHeight || DEFAULT_RECOVERY_LAYOUT_CONFIG.templates.catalogHeight), 360, 1400),
            composerHeight: clampLayoutPercent(Number(templates?.composerHeight || DEFAULT_RECOVERY_LAYOUT_CONFIG.templates.composerHeight), 480, 1600),
            composerMode: templates?.composerMode === "column" ? "column" : "row",
            composerPreviewPercent: clampLayoutPercent(Number(templates?.composerPreviewPercent || DEFAULT_RECOVERY_LAYOUT_CONFIG.templates.composerPreviewPercent), 34, 62)
        }
    };
}
